print("[TurboSoccerAI 0.8.0] Starter executing")
local env=_G
if type(getgenv)=="function" then
local ok,value=pcall(getgenv)
if ok and type(value)=="table" then env=value end
end
local ticket={cancelled=false}
local previous=env.__TurboSoccerBootstrap
if type(previous)=="table" then
previous.cancelled=true
if previous.gui then pcall(function()previous.gui:Destroy()end)end
end
env.__TurboSoccerBootstrap=ticket
local gui,label,errorText
local function live()
return not ticket.cancelled and env.__TurboSoccerBootstrap==ticket
and(not ticket.owner or env.__TurboSoccerOverhaulLoader==ticket.owner and not ticket.owner.cancelled)
end
local function status(message)
if label and gui and gui.Parent and live()then label.Text=message end
end
local mounted,mountError=pcall(function()
local parents={}
if type(gethui)=="function" then
local ok,parent=pcall(gethui)
if ok and typeof(parent)=="Instance" then parents[#parents+1]=parent end
end
local player=game:GetService("Players").LocalPlayer
if player then
local parent=player:FindFirstChildOfClass("PlayerGui")
if parent then parents[#parents+1]=parent end
end
local ok,core=pcall(function()return game:GetService("CoreGui")end)
if ok and typeof(core)=="Instance" then parents[#parents+1]=core end
gui=Instance.new("ScreenGui")
gui.Name="TurboSoccerAIBootstrap";gui.ResetOnSpawn=false;gui.Enabled=true;gui.DisplayOrder=100002
ticket.gui=gui
local attached=false
for _,parent in ipairs(parents)do
local accepted=pcall(function()gui.Parent=parent;assert(gui.Parent==parent)end)
if accepted then attached=true;break end
end
assert(attached,"Cannot show UI. Join a game and retry.")
local box=Instance.new("Frame")
box.Size=UDim2.new(.8,0,0,156);box.Position=UDim2.new(.1,0,0,72)
box.BackgroundColor3=Color3.fromRGB(22,25,34);box.Parent=gui
label=Instance.new("TextLabel")
label.Size=UDim2.new(1,-24,0,102);label.Position=UDim2.fromOffset(12,4)
label.BackgroundTransparency=1;label.TextColor3=Color3.fromRGB(240,244,255)
label.TextSize=15;label.TextWrapped=true;label.Text="Turbo AI 0.8.0: starting...";label.Parent=box
local copy=Instance.new("TextButton")
copy.Size=UDim2.new(.65,-12,0,34);copy.Position=UDim2.fromOffset(12,112)
copy.Text="Copy startup error";copy.Parent=box
copy.Activated:Connect(function()
if type(setclipboard)=="function" then
local ok=pcall(setclipboard,errorText or label.Text)
copy.Text=ok and "Copied" or "Check executor console"
else copy.Text="Check executor console" end
end)
local close=Instance.new("TextButton")
close.Size=UDim2.new(.35,-12,0,34);close.Position=UDim2.new(.65,0,0,112)
close.Text="Close";close.Parent=box
close.Activated:Connect(function()ticket.cancelled=true;gui:Destroy()end)
end)
if not mounted then
if gui then pcall(function()gui:Destroy()end)end
warn("[TurboSoccerAI] Starter GUI: "..tostring(mountError))
end
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local digits={}
for i=1,#alphabet do digits[alphabet:byte(i)]=i-1 end
local function base64(source)
source=source:gsub("%s","")
assert(#source%4==0,"Incomplete script; paste the whole file")
local parts={}
for i=1,#source,4 do
local ca,cb,cc,cd=source:byte(i,i+3)
local a,b,c,d=digits[ca],digits[cb],digits[cc],digits[cd]
assert(a and b,"Invalid packaged data")
if cc==61 then assert(i+3==#source and cd==61,"Invalid padding");c=0 end
if cd==61 then assert(i+3==#source,"Invalid padding");d=0 end
assert(c and d,"Invalid packaged data")
local part=string.char(a*4+math.floor(b/16),(b%16)*16+math.floor(c/4),(c%4)*64+d)
if cc==61 then part=part:sub(1,1)elseif cd==61 then part=part:sub(1,2)end
parts[#parts+1]=part
end
return table.concat(parts)
end
local function checksum(source)
local a,b=1,0
for i=1,#source do a=(a+source:byte(i))%65521;b=(b+a)%65521 end
return b*65536+a
end
local function compactPinned(source)
assert(type(source)=="string" and not source:find("%[=*%[")and not source:find("\\\r?\n"),
"Unsupported pinned source layout")
local out={}
for line in(source.."\n"):gmatch("(.-)\n")do
line=line:match("^%s*(.-)%s*$")
local notice=line:find("CC BY",1,true)or line:find("Nexto:",1,true)
or line:find("port/weights",1,true)or line:find("Port/weights",1,true)
if line~="" and(line:sub(1,2)~="--" or notice)then out[#out+1]=line end
end
return table.concat(out,"\n").."\n"
end
local function reconstruct(record,base,patch)
base=compactPinned(base)
assert(#base==record.baseBytes and checksum(base)==record.baseChecksum,"Pinned module layout changed")
local out={};local at,total=1,0
while at<=#patch do
local op=patch:byte(at);at=at+1
local part
if op==0 then
local a,b,c,d=patch:byte(at,at+3);at=at+4
assert(d,"Incomplete COPY command")
local offset,length=a+b*256,c+d*256
assert(length>0 and offset+length<=#base,"Invalid COPY command")
part=base:sub(offset+1,offset+length)
elseif op==1 then
local a,b=patch:byte(at,at+1);at=at+2
assert(b,"Incomplete INSERT command")
local length=a+b*256
assert(length>0 and at+length-1<=#patch,"Invalid INSERT command")
part=patch:sub(at,at+length-1);at=at+length
else error("Unknown patch command")end
total=total+#part;assert(total<=record.bytes,"Decoded module too large")
out[#out+1]=part
end
local source=table.concat(out)
assert(#source==record.bytes and checksum(source)==record.checksum,"Reconstructed module changed")
return source
end
local function unpackModule(record,name,sourceSupplier)
assert(live(),"Startup closed or replaced")
status("Turbo AI 0.8.0: preparing "..name.."...")
local expected=record.patchBytes or record.bytes
local expectedChecksum=record.patchChecksum or record.checksum
local data=base64(record.data)
local out={};local n,at=0,1
local sum1,sum2=1,0
local nextYield=8192
local function append(char)
n=n+1;assert(n<=expected,"Decoded module too large")
out[n]=char;sum1=(sum1+char:byte())%65521;sum2=(sum2+sum1)%65521
end
while at<=#data do
local flags=data:byte(at);at=at+1
assert(at<=#data,"Empty packaged reference group")
for bit=0,7 do
if at>#data then assert(flags<2^bit,"Incomplete reference group");break end
if math.floor(flags/2^bit)%2==1 then
local lo,hi=data:byte(at,at+1);at=at+2
assert(hi,"Incomplete packaged reference")
local distance=lo+(hi%32)*256+1
local count=math.floor(hi/32)+3
if count==10 then
local extra=data:byte(at);at=at+1
assert(extra,"Missing reference length");count=count+extra
end
assert(distance>0 and distance<=n,"Invalid packaged reference")
for _=1,count do append(out[n-distance+1])end
else append(data:sub(at,at));at=at+1 end
end
if n>=nextYield then
if task and type(task.wait)=="function" then task.wait()end
assert(live(),"Startup closed or replaced");nextYield=n+8192
end
end
assert(n==expected and sum2*65536+sum1==expectedChecksum,
"Packaged module changed or was truncated; copy the complete script")
local source=table.concat(out)
if record.baseBytes then
assert(type(sourceSupplier)=="function","Verified source is missing")
source=reconstruct(record,sourceSupplier(),source)
end
return source
end
local required={"Loader","Adaptive","Aerial","Tactics","Opponent","Strategy","Dashboard","Runtime"}
local function validateRecords(records)
assert(type(records)=="table","Packaged module directory is missing")
for _,name in ipairs(required)do
local r=records[name]
assert(type(r)=="table","Packaged module is missing: "..name)
assert(type(r.bytes)=="number" and r.bytes%1==0 and r.bytes>0 and r.bytes<64000
and type(r.checksum)=="number" and r.checksum%1==0 and r.checksum>=0 and r.checksum<4294967296
and type(r.data)=="string" and #r.data>0,"Invalid packaged module: "..name)
end
end
local function fail(message)
if not live()then return end
errorText="Turbo AI 0.8.0 startup failed: "..tostring(message)
status(errorText);warn(errorText)
if not mounted then
pcall(function()game:GetService("StarterGui"):SetCore("SendNotification",
{Title="Turbo AI startup failed",Text=tostring(message),Duration=20})end)
end
end
