local function start()
if not live()then return end
local ok,result=pcall(function()
assert(type(loadstring)=="function","Arceus is missing loadstring")
validateRecords(records)
local function compile(record,name,sourceSupplier)
local source=unpackModule(record,name,sourceSupplier)
assert(#source<64000,"Module exceeds 64 KB")
local run,why=loadstring(source,"=TurboAI/"..name)
assert(run,"Cannot compile "..name..": "..tostring(why))
return run
end
local factories={}
for _,role in ipairs(required)do
if role~="Loader" then
local name=role
factories[name]=function(sourceSupplier)
